import{_ as e,o as a,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"硅酸盐 · 链状 / 带状","description":"","frontmatter":{"title":"硅酸盐 · 链状 / 带状","mineralGroup":"silicates-chain"},"headers":[],"relativePath":"zh/classification/mineral-groups/silicates-chain.md","filePath":"zh/classification/mineral-groups/silicates-chain.md","lastUpdated":1790876393000}'),d={name:"zh/classification/mineral-groups/silicates-chain.md"};function l(n,t,o,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="硅酸盐-·-链状-带状" tabindex="-1">硅酸盐 · 链状 / 带状 <a class="header-anchor" href="#硅酸盐-·-链状-带状" aria-label="Permalink to &quot;硅酸盐 · 链状 / 带状&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>链状硅酸盐包含两个重要宝石族：</p><ul><li><strong>辉石族（单链）</strong>：硬玉（翡翠）、透辉石、蔷薇辉石（部分属 此）、锂辉石（孔赛石）</li><li><strong>角闪石族（双链）</strong>：软玉（和田玉）、阳起石、透闪石 翡翠（硬玉）与软玉（透闪石）是中国传统&quot;玉&quot;的两大来源，但 化学与晶体结构完全不同。</li></ul><h2 id="化学式类型" tabindex="-1">化学式类型 <a class="header-anchor" href="#化学式类型" aria-label="Permalink to &quot;化学式类型&quot;">​</a></h2><p>M·SiO₃ / M₇Si₈O₂₂(OH)₂</p><h2 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h2><p>[SiO₄] 四面体通过共享两个顶角氧连接为单链（辉石）或共享两 个加一个为双链（角闪石）。链间由金属阳离子（如 Ca、Mg、Fe） 和 OH⁻ 桥接。链结构沿 c 轴延伸，使晶体常呈柱状或纤维状习性。</p><h2 id="代表性宝石" tabindex="-1">代表性宝石 <a class="header-anchor" href="#代表性宝石" aria-label="Permalink to &quot;代表性宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>化学式</th><th>亚族</th></tr></thead><tbody><tr><td>Jadeite (Burmese Jade) / 翡翠</td><td>NaAlSi₂O₆</td><td>pyroxene</td></tr><tr><td>Nephrite / 软玉</td><td>Ca₂(Mg,Fe)₅Si₈O₂₂(OH)₂</td><td>amphibole</td></tr><tr><td>Spodumene (Kunzite) / 孔赛石</td><td>LiAlSi₂O₆</td><td>pyroxene</td></tr><tr><td>Spodumene (Hiddenite) / 翠绿锂辉石</td><td>LiAlSi₂O₆ + Cr</td><td>pyroxene</td></tr><tr><td>Diopside / 透辉石</td><td>CaMgSi₂O₆</td><td>pyroxene</td></tr><tr><td>Rhodonite / 蔷薇辉石</td><td>MnSiO₃</td><td>pyroxenoid</td></tr><tr><td>Actinolite / 阳起石</td><td>Ca₂(Mg,Fe)₅Si₈O₂₂(OH)₂</td><td>amphibole</td></tr></tbody></table><p><em>详见<a href="./intro.html">矿物组总览</a>。</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA：宝石的矿物种、品种与矿物组</a><span>矿物种、宝石品种与矿物组的层级关系</span><small>打开来源 ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat 矿物数据库</a><span>矿物名称、化学组成与分类检索</span><small>打开来源 ↗</small></li></ul></aside>',12)])])}const u=e(d,[["render",l]]);export{m as __pageData,u as default};
